const _ = `@startuml
Alice->Bob : Hello
return ok
@enduml
`;

export const NodeView = ({
    node,
    updateAttributes,
    deleteNode
}: Partial<ReactNodeViewProps<PlantUMLAttributes>>) => {
    const attrs = node!.attrs as PlantUMLAttributes;
    const [copied, setCopied] = useState(false);

    const currentValue = attrs.value ?? _;

    const handleCopy = useCallback(() => {
        if (!currentValue) {
            return;
        }

        void navigator.clipboard.writeText(currentValue);
        setCopied(true);

        const timeout = setTimeout(() => {
            setCopied(false);
        }, 2000);

        return () => clearTimeout(timeout);
    }, [currentValue]);

    return (
        <NodeViewWrapper data-slot="plantuml" data-value={attrs.value}>
            <div className="p-px">
                <Tabs
                    defaultValue="preview"
                    className="gap-0 overflow-hidden rounded-xl border border-border bg-card shadow-xs"
                >
                    <div className="flex flex-wrap items-center justify-between gap-2 border-b bg-muted/40 px-3 py-2">
                        <div className="flex items-center gap-3">
                            <div className="flex items-center gap-1.5 text-xs font-semibold text-foreground">
                                <RiOrganizationChart className="size-4 text-primary" />
                                <span>PlantUML</span>
                            </div>

                            <TabsList className="h-7 bg-muted/80 p-0.5">
                                <TabsTrigger
                                    value="preview"
                                    className="h-6 gap-1.5 px-2.5 text-xs"
                                >
                                    <EyeIcon className="size-3.5" />
                                    <span>Pré-visualização</span>
                                </TabsTrigger>
                                <TabsTrigger
                                    value="code"
                                    className="h-6 gap-1.5 px-2.5 text-xs"
                                >
                                    <Code2Icon className="size-3.5" />
                                    <span>Código</span>
                                </TabsTrigger>
                            </TabsList>
                        </div>

                        <div className="flex items-center gap-1">
                            <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                className="h-7 gap-1 px-2 text-xs text-muted-foreground hover:text-foreground"
                                onClick={handleCopy}
                                title="Copiar código PlantUML"
                            >
                                {copied ? (
                                    <>
                                        <CheckIcon className="size-3.5 text-emerald-600 dark:text-emerald-400" />
                                        <span className="text-emerald-600 dark:text-emerald-400">
                                            Copiado
                                        </span>
                                    </>
                                ) : (
                                    <>
                                        <CopyIcon className="size-3.5" />
                                        <span>Copiar</span>
                                    </>
                                )}
                            </Button>

                            {deleteNode ? (
                                <Button
                                    type="button"
                                    variant="ghost"
                                    size="icon-xs"
                                    className="size-7 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                                    onClick={deleteNode}
                                    title="Remover diagrama"
                                >
                                    <Trash2Icon className="size-3.5" />
                                </Button>
                            ) : null}
                        </div>
                    </div>

                    <TabsContent
                        value="preview"
                        className="m-0 min-h-[260px] bg-card p-0"
                    >
                        <NodeMapping {...attrs} />
                    </TabsContent>

                    <TabsContent value="code" className="m-0 p-0">
                        <textarea
                            className="min-h-[260px] w-full resize-y border-0 bg-muted/20 p-4 font-mono text-xs leading-relaxed outline-none placeholder:text-muted-foreground focus-visible:ring-0"
                            value={currentValue}
                            placeholder="Escreva o diagrama PlantUML aqui..."
                            spellCheck={false}
                            onChange={e => {
                                if (updateAttributes) {
                                    updateAttributes({
                                        value: e.currentTarget.value
                                    });
                                }
                            }}
                        />
                    </TabsContent>
                </Tabs>
            </div>
        </NodeViewWrapper>
    );
};

import { renderToString } from '@plantuml/core';
import '@plantuml/core/viz-global.js';
import { RiGhostLine } from '@remixicon/react';
import { keepPreviousData, useQuery } from '@tanstack/react-query';
import { AlertCircleIcon } from 'lucide-react';
import { useTheme } from 'next-themes';

import { Spinner } from '@components/extensions/ui/spinner';

import { type PlantUMLAttributes } from './types';

export const NodeMapping = (attrs: PlantUMLAttributes) => {
    const { resolvedTheme } = useTheme();

    const trimmedValue = attrs.value?.trim() ?? '';

    const { data, isPending, isFetching, isError, error } = useQuery({
        queryKey: ['plantuml', trimmedValue, resolvedTheme],
        queryFn: async (): Promise<string> => {
            if (!trimmedValue) {
                throw new Error('Código do diagrama não fornecido');
            }

            return new Promise((resolve, reject) => {
                renderToString(
                    trimmedValue.split('\n'),
                    (svg: string) => resolve(svg),
                    (message: unknown) => {
                        const errorMsg =
                            typeof message === 'string'
                                ? message
                                : message instanceof Error
                                  ? message.message
                                  : 'Erro ao compilar diagrama PlantUML';

                        reject(new Error(errorMsg));
                    },
                    { dark: resolvedTheme === 'dark' }
                );
            });
        },
        enabled: Boolean(trimmedValue),
        placeholderData: keepPreviousData,
        staleTime: Infinity,
        gcTime: 1000 * 60 * 60 * 24,
        retry: false
    });

    if (!trimmedValue) {
        return (
            <div className="flex min-h-[220px] w-full flex-col items-center justify-center gap-2 rounded-lg border border-dashed border-muted-foreground/20 p-6 text-center text-muted-foreground">
                <RiGhostLine className="size-6 shrink-0 opacity-40" />
                <span className="text-xs">
                    Nenhum diagrama PlantUML definido. Alterne para a aba
                    "Código" para escrever.
                </span>
            </div>
        );
    }

    if (isPending && !data) {
        return (
            <div className="flex min-h-[220px] w-full items-center justify-center">
                <Spinner />
            </div>
        );
    }

    if (isError && !data) {
        return (
            <div className="flex min-h-[220px] w-full flex-col items-center justify-center gap-2 rounded-lg border border-destructive/20 bg-destructive/5 p-6 text-center text-destructive">
                <AlertCircleIcon className="size-5 shrink-0" />
                <span className="text-xs font-medium">
                    Erro ao compilar diagrama PlantUML
                </span>
                <span className="max-w-md text-[11px] opacity-80">
                    {error instanceof Error
                        ? error.message
                        : 'Erro de sintaxe no código'}
                </span>
            </div>
        );
    }

    if (!data) {
        return null;
    }

    const svgContent = typeof data === 'string' ? data : '';

    return (
        <div className="relative flex size-full min-h-[220px] items-center justify-center overflow-auto p-4">
            {isFetching ? (
                <div className="absolute top-2 right-2 z-10 flex items-center gap-1.5 rounded-full border bg-background/80 px-2 py-0.5 text-[10px] text-muted-foreground shadow-xs backdrop-blur">
                    <Spinner className="size-3" />
                    <span>A actualizar...</span>
                </div>
            ) : null}

            {isError ? (
                <div className="text-destructive-foreground absolute inset-x-2 bottom-2 z-10 flex items-center gap-2 rounded-lg border border-destructive/30 bg-destructive/90 px-3 py-1.5 text-xs shadow-sm backdrop-blur">
                    <AlertCircleIcon className="size-4 shrink-0" />
                    <span className="truncate">
                        {error instanceof Error
                            ? error.message
                            : 'Erro de sintaxe no código PlantUML'}
                    </span>
                </div>
            ) : null}

            <div
                className="flex size-full items-center justify-center [&_svg]:h-auto [&_svg]:max-w-full"
                dangerouslySetInnerHTML={{ __html: svgContent }}
                suppressHydrationWarning
            />
        </div>
    );
};

